        "content": "/**\n * JSON Validator - Validates JSON input from stdin\n *\n * Usage: echo '{\"key\": \"value\"}' | bun run src/scripts/validate-json.ts\n *\n * Exit codes:\n *   0 - Valid JSON\n *   1 - Invalid JSON\n */\n\nasync function readStdin(): Promise<string> {\n  const chunks: Uint8Array[] = [];\n  const reader = Bun.stdin.stream().getReader();\n\n  while (true) {\n    const { done, value } = await reader.read();\n    if (done) break;\n    if (value) chunks.push(value);\n  }\n\n  const combined = new Uint8Array(chunks.reduce((acc, chunk) => acc + chunk.length, 0));\n  let offset = 0;\n  for (const chunk of chunks) {\n    combined.set(chunk, offset);\n    offset += chunk.length;\n  }\n\n  return new TextDecoder().decode(combined);\n}\n\nfunction extractErrorPosition(error: SyntaxError, input: string): { line: number; column: number } | null {\n  const message = error.message;\n\n  // Try to extract position from Bun/V8 error message format\n  // Common formats: \"at position N\", \"at line N column M\", \"position N\"\n  const positionMatch = message.match(/position\\s+(\\d+)/i);\n  if (positionMatch) {\n    const position = parseInt(positionMatch[1], 10);\n    return positionToLineColumn(input, position);\n  }\n\n  const lineColMatch = message.match(/line\\s+(\\d+)\\s+column\\s+(\\d+)/i);\n  if (lineColMatch) {\n    return {\n      line: parseInt(lineColMatch[1], 10),\n      column: parseInt(lineColMatch[2], 10),\n    };\n  }\n\n  return null;\n}\n\nfunction positionToLineColumn(input: string, position: number): { line: number; column: number } {\n  const lines = input.substring(0, position).split('\\n');\n  return {\n    line: lines.length,\n    column: lines[lines.length - 1].length + 1,\n  };\n}\n\nasync function main(): Promise<void> {\n  const input = await readStdin();\n\n  if (input.trim() === '') {\n    console.error('Error: No input provided');\n    process.exit(1);\n  }\n\n  try {\n    JSON.parse(input);\n    console.log('Valid JSON');\n    process.exit(0);\n  } catch (error) {\n    if (error instanceof SyntaxError) {\n      const position = extractErrorPosition(error, input);\n      if (position) {\n        console.error(`Invalid JSON at line ${position.line}, column ${position.column}`);\n        console.error(`Error: ${error.message}`);\n      } else {\n        console.error(`Invalid JSON: ${error.message}`);\n      }\n    } else {\n      console.error('Unexpected error:', error);\n    }\n    process.exit(1);\n  }\n}\n\nmain();\n"
