/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Create a customizable greeting message.
 * @param type - The type of greeting (e.g., "hello", "hi", "good morning")
 * @param name - The name of the person to greet
 * @returns The formatted greeting message
 */
export function createGreeting(type: string, name: string): string {
  const capitalizedType = type.charAt(0).toUpperCase() + type.slice(1).toLowerCase();
  return `${capitalizedType}, ${name}!`;
}

