        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { validateJsonString, validateJsonFile, validateLargeJsonFile, parseArgs, main } from \"./validate-json\";\nimport { mkdtemp, rm } from \"node:fs/promises\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\n\ndescribe(\"validateJsonString\", () => {\n  test(\"returns valid for valid JSON object\", () => {\n    const result = validateJsonString('{\"name\": \"test\", \"value\": 123}');\n    expect(result.valid).toBe(true);\n    expect(result.error).toBeUndefined();\n  });\n\n  test(\"returns valid for valid JSON array\", () => {\n    const result = validateJsonString('[1, 2, 3, \"four\"]');\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"returns valid for JSON primitives\", () => {\n    expect(validateJsonString(\"true\").valid).toBe(true);\n    expect(validateJsonString(\"false\").valid).toBe(true);\n    expect(validateJsonString(\"null\").valid).toBe(true);\n    expect(validateJsonString(\"123\").valid).toBe(true);\n    expect(validateJsonString('\"string\"').valid).toBe(true);\n  });\n\n  test(\"returns invalid for malformed JSON\", () => {\n    const result = validateJsonString('{\"name\": \"test\"');\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n\n  test(\"returns invalid for trailing comma\", () => {\n    const result = validateJsonString('{\"name\": \"test\",}');\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"returns invalid for single quotes\", () => {\n    const result = validateJsonString(\"{'name': 'test'}\");\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"returns invalid for empty string\", () => {\n    const result = validateJsonString(\"\");\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"strict mode accepts valid values\", () => {\n    expect(validateJsonString('{\"a\": 1}', { strict: true }).valid).toBe(true);\n    expect(validateJsonString(\"[1, 2]\", { strict: true }).valid).toBe(true);\n    expect(validateJsonString(\"null\", { strict: true }).valid).toBe(true);\n  });\n});\n\ndescribe(\"validateJsonFile\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"json-validate-test-\"));\n  });\n\n  afterAll(async () => {\n    await rm(tempDir, { recursive: true, force: true });\n  });\n\n  test(\"validates a valid JSON file\", async () => {\n    const filePath = join(tempDir, \"valid.json\");\n    await Bun.write(filePath, '{\"test\": true}');\n\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"returns error for invalid JSON file\", async () => {\n    const filePath = join(tempDir, \"invalid.json\");\n    await Bun.write(filePath, '{\"test\": true');\n\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"returns error for non-existent file\", async () => {\n    const result = await validateJsonFile(\"/nonexistent/path/file.json\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n\n  test(\"handles nested JSON structures\", async () => {\n    const filePath = join(tempDir, \"nested.json\");\n    const nestedJson = JSON.stringify({\n      level1: {\n        level2: {\n          level3: {\n            array: [1, 2, { nested: true }],\n          },\n        },\n      },\n    });\n    await Bun.write(filePath, nestedJson);\n\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"handles unicode content\", async () => {\n    const filePath = join(tempDir, \"unicode.json\");\n    await Bun.write(filePath, '{\"emoji\": \"Hello World\"}');\n\n    const result = await validateJsonFile(filePath);\n    expect(result.valid).toBe(true);\n  });\n});\n\ndescribe(\"validateLargeJsonFile\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"json-validate-large-\"));\n  });\n\n  afterAll(async () => {\n    await rm(tempDir, { recursive: true, force: true });\n  });\n\n  test(\"validates a file using streaming\", async () => {\n    const filePath = join(tempDir, \"stream-test.json\");\n    await Bun.write(filePath, '{\"streaming\": \"test\"}');\n\n    const result = await validateLargeJsonFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"returns error for invalid JSON via streaming\", async () => {\n    const filePath = join(tempDir, \"stream-invalid.json\");\n    await Bun.write(filePath, '{\"incomplete\":');\n\n    const result = await validateLargeJsonFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n  });\n});\n\ndescribe(\"parseArgs\", () => {\n  test(\"parses file paths\", () => {\n    const result = parseArgs([\"file1.json\", \"file2.json\"]);\n    expect(result.files).toEqual([\"file1.json\", \"file2.json\"]);\n    expect(result.options.quiet).toBeUndefined();\n    expect(result.options.strict).toBeUndefined();\n  });\n\n  test(\"parses --quiet flag\", () => {\n    const result = parseArgs([\"file.json\", \"--quiet\"]);\n    expect(result.files).toEqual([\"file.json\"]);\n    expect(result.options.quiet).toBe(true);\n  });\n\n  test(\"parses -q flag\", () => {\n    const result = parseArgs([\"-q\", \"file.json\"]);\n    expect(result.files).toEqual([\"file.json\"]);\n    expect(result.options.quiet).toBe(true);\n  });\n\n  test(\"parses --strict flag\", () => {\n    const result = parseArgs([\"file.json\", \"--strict\"]);\n    expect(result.files).toEqual([\"file.json\"]);\n    expect(result.options.strict).toBe(true);\n  });\n\n  test(\"parses -s flag\", () => {\n    const result = parseArgs([\"file.json\", \"-s\"]);\n    expect(result.files).toEqual([\"file.json\"]);\n    expect(result.options.strict).toBe(true);\n  });\n\n  test(\"parses combined flags and files\", () => {\n    const result = parseArgs([\"--quiet\", \"a.json\", \"-s\", \"b.json\"]);\n    expect(result.files).toEqual([\"a.json\", \"b.json\"]);\n    expect(result.options.quiet).toBe(true);\n    expect(result.options.strict).toBe(true);\n  });\n});\n\ndescribe(\"main CLI\", () => {\n  let tempDir: string;\n\n  beforeAll(async () => {\n    tempDir = await mkdtemp(join(tmpdir(), \"json-validate-cli-\"));\n  });\n\n  afterAll(async () => {\n    await rm(tempDir, { recursive: true, force: true });\n  });\n\n  test(\"returns 0 for valid JSON files\", async () => {\n    const filePath = join(tempDir, \"cli-valid.json\");\n    await Bun.write(filePath, '{\"valid\": true}');\n\n    const exitCode = await main([filePath, \"--quiet\"]);\n    expect(exitCode).toBe(0);\n  });\n\n  test(\"returns 1 for invalid JSON files\", async () => {\n    const filePath = join(tempDir, \"cli-invalid.json\");\n    await Bun.write(filePath, \"not json\");\n\n    const exitCode = await main([filePath, \"--quiet\"]);\n    expect(exitCode).toBe(1);\n  });\n\n  test(\"returns 1 when no files provided\", async () => {\n    const exitCode = await main([\"--quiet\"]);\n    expect(exitCode).toBe(1);\n  });\n\n  test(\"validates multiple files\", async () => {\n    const validPath = join(tempDir, \"multi-valid.json\");\n    const invalidPath = join(tempDir, \"multi-invalid.json\");\n    await Bun.write(validPath, \"{}\");\n    await Bun.write(invalidPath, \"{broken\");\n\n    const exitCode = await main([validPath, invalidPath, \"-q\"]);\n    expect(exitCode).toBe(1);\n  });\n});\n"
