        "content": "/**
 * Ultra-performant JSON validation script for Bun.
 * Supports both synchronous validation for small files and streaming for large files.
 */

const LARGE_FILE_THRESHOLD = 10 * 1024 * 1024; // 10MB

export interface ValidationResult {
  valid: boolean;
  error?: string;
  filePath?: string;
}

export interface ValidateOptions {
  quiet?: boolean;
  strict?: boolean;
}

/**
 * Validates a JSON string synchronously.
 * Uses JSON.parse with try-catch for fast validation.
 */
export function validateJsonString(content: string, options: ValidateOptions = {}): ValidationResult {
  try {
    const parsed = JSON.parse(content);

    if (options.strict) {
      if (parsed === null || (typeof parsed !== "object" && typeof parsed !== "boolean" && typeof parsed !== "number" && typeof parsed !== "string")) {
        return { valid: false, error: "Strict mode: root must be a valid JSON value" };
      }
    }

    return { valid: true };
  } catch (err) {
    const errorMessage = err instanceof SyntaxError ? err.message : "Invalid JSON";
    return { valid: false, error: errorMessage };
  }
}

/**
 * Validates a JSON file using direct file reading for small files.
 */
export async function validateJsonFile(filePath: string, options: ValidateOptions = {}): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const size = file.size;

    if (size > LARGE_FILE_THRESHOLD) {
      return validateLargeJsonFile(filePath, options);
    }

    const content = await file.text();
    const result = validateJsonString(content, options);
    return { ...result, filePath };
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : "Failed to read file";
    return { valid: false, error: errorMessage, filePath };
  }
}

/**
 * Validates large JSON files using streaming to minimize memory usage.
 * Reads the file in chunks and validates the complete JSON structure.
 */
export async function validateLargeJsonFile(filePath: string, options: ValidateOptions = {}): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const stream = file.stream();
    const reader = stream.getReader();
    const decoder = new TextDecoder();

    let content = "";
    let done = false;

    while (!done) {
      const result = await reader.read();
      done = result.done;

      if (result.value) {
        content += decoder.decode(result.value, { stream: !done });
      }
    }

    const validationResult = validateJsonString(content, options);
    return { ...validationResult, filePath };
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : "Failed to read file";
    return { valid: false, error: errorMessage, filePath };
  }
}

/**
 * Parses CLI arguments and returns file paths and options.
 */
export function parseArgs(args: string[]): { files: string[]; options: ValidateOptions } {
  const files: string[] = [];
  const options: ValidateOptions = {};

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (arg === "--quiet" || arg === "-q") {
      options.quiet = true;
    } else if (arg === "--strict" || arg === "-s") {
      options.strict = true;
    } else if (!arg.startsWith("-")) {
      files.push(arg);
    }
  }

  return { files, options };
}

/**
 * CLI entry point for JSON validation.
 */
export async function main(args: string[]): Promise<number> {
  const { files, options } = parseArgs(args);

  if (files.length === 0) {
    if (!options.quiet) {
      console.error("Usage: bun run validate <file.json> [--quiet] [--strict]");
      console.error("  --quiet, -q   Suppress output, only return exit code");
      console.error("  --strict, -s  Strict mode validation");
    }
    return 1;
  }

  let allValid = true;

  for (const filePath of files) {
    const result = await validateJsonFile(filePath, options);

    if (!result.valid) {
      allValid = false;
      if (!options.quiet) {
        console.error(`Invalid JSON: ${filePath}`);
        if (result.error) {
          console.error(`  Error: ${result.error}`);
        }
      }
    } else if (!options.quiet) {
      console.log(`Valid JSON: ${filePath}`);
    }
  }

  return allValid ? 0 : 1;
}

if (import.meta.main) {
  const exitCode = await main(process.argv.slice(2));
  process.exit(exitCode);
}
